                    (h, l) = ddSum1(0.5, -h, -l);
                }
                else
                {
                    (h, l) = ddSum1(-0.5, -h, -l);
                }
            }

            if (negx)
            {
                if (!negz)
                {
                    (h, l) = ddSum1(-1.0, h, l);
                }
                else
                {
                    (h, l) = ddSum1(1.0, h, l);
                }
            }

            return (errFast[i], h, l);
        }






        ulong uy = Polyfill.DoubleToUInt64Bits(y), ux = Polyfill.DoubleToUInt64Bits(x);
        ulong ay = uy & Mask, ax = ux & Mask;
        int ey = (int)(ay >> 52), ex = (int)(ax >> 52);

        if (ey == 0x7ff || ex == 0x7ff)
        {
            if (isNaN(ay) || isNaN(ax))
            {
                return y + x;
            }
            if (isInf(ay) && isInf(ax))
            {
                if (x < 0.0)
                {
                    return y > 0.0 ? 0.75 : -0.75;
                }
                return y > 0.0 ? 0.25 : -0.25;
            }

            if (isInf(ax))
            {
                if (x < 0.0)
                {
                    return (uy >> 63) != 0 ? -1.0 : 1.0;
                }
                return CopySign(0.0, y);
            }

            return y > 0.0 ? 0.5 : -0.5;
        }

        if (ay == 0 || ax == 0)
        {
            if (ay == 0 && ax == 0)
            {
                if (ux == 0)
                {
                    return y;
                }
                return uy == 0 ? 1.0 : -1.0;
            }
            if (ay == 0)
            {
                if (x > 0.0)
                {
                    return y;
                }
                return uy == 0 ? 1.0 : -1.0;
            }
            return y > 0.0 ? 0.5 : -0.5;
        }

        if (54 <= ex && ex <= 2044 && 54 <= ey && ey <= 2044 && -341 <= ey - ex && ey - ex <= 341)
        {
            var (err, h, l) = atan2piFast(y, x);
            double left = h + FusedMultiplyAdd(h, -err, l);
            double right = h + FusedMultiplyAdd(h, err, l);
            if (left == right)
            {
                return left;
            }
        }

        return atan2PiAccurate(y, x);
    }
}
